function safeStorageFileName(name) {
  const base = String(name || "recording")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9._-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^[-.]+|[-.]+$/g, "")
    .slice(0, 90);
  return base || "recording";
}
function encodeStoragePath(path) {
  return path.split("/").map(encodeURIComponent).join("/");
}
async function uploadAudioToStorage(file) {
  if(!file) throw new Error("No file selected.");
  if(!file.type?.startsWith("audio/") && !/\.(mp3|m4a|wav|aac|ogg|opus)$/i.test(file.name || "")) {
    throw new Error("Please choose an audio file, such as MP3, M4A, WAV, AAC, or OGG.");
  }
  const path = `recordings/${Date.now()}-${Math.random().toString(36).slice(2)}-${safeStorageFileName(file.name)}`;
  const encodedPath = encodeStoragePath(path);
  const res = await fetch(`${SUPA_URL}/storage/v1/object/${STORAGE_AUDIO_BUCKET}/${encodedPath}`, {
    method: "POST",
    headers: {
      "apikey": SUPA_KEY,
      "Authorization": `Bearer ${SUPA_KEY}`,
      "Content-Type": file.type || "application/octet-stream",
      "x-upsert": "false",
    },
    body: file,
  });
  if(!res.ok) {
    const e = await res.text();
    console.error("Supabase Storage upload error:", e);
    throw new Error(e || "Upload failed. Check that the tbi-recordings storage bucket and upload policy exist.");
  }
  return `${SUPA_URL}/storage/v1/object/public/${STORAGE_AUDIO_BUCKET}/${encodedPath}`;
}

async function uploadPdfToStorage(file) {
  if(!file) throw new Error("No file selected.");
  const looksLikePdf = file.type === "application/pdf" || /\.pdf$/i.test(file.name || "");
  if(!looksLikePdf) throw new Error("Please choose a PDF file.");
  const path = `pdfs/${Date.now()}-${Math.random().toString(36).slice(2)}-${safeStorageFileName(file.name || "document.pdf")}`;
  const encodedPath = encodeStoragePath(path);
  const res = await fetch(`${SUPA_URL}/storage/v1/object/${STORAGE_PDF_BUCKET}/${encodedPath}`, {
    method: "POST",
    headers: {
      "apikey": SUPA_KEY,
      "Authorization": `Bearer ${SUPA_KEY}`,
      "Content-Type": "application/pdf",
      "Content-Disposition": `inline; filename="${safeStorageFileName(file.name || "document.pdf")}"`,
      "x-upsert": "false",
    },
    body: file,
  });
  if(!res.ok) {
    const e = await res.text();
    console.error("Supabase PDF Storage upload error:", e);
    throw new Error(e || "Upload failed. Check that the tbi-pdfs storage bucket and upload policy exist.");
  }
  return `${SUPA_URL}/storage/v1/object/public/${STORAGE_PDF_BUCKET}/${encodedPath}`;
}

async function sb(path, method="GET", body=null, extra_headers={}) {
  const headers = {
    "apikey": SUPA_KEY,
    "Authorization": `Bearer ${SUPA_KEY}`,
    "Content-Type": "application/json",
    ...extra_headers,
  };
  const res = await fetch(`${SUPA_URL}/rest/v1/${path}`, {
    method,
    headers,
    body: body != null ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) {
    const e = await res.text();
    console.error(`Supabase ${method} ${path} error:`, e);
    throw new Error(e);
  }
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

