function genId() { return Date.now().toString(36) + Math.random().toString(36).slice(2); }

function isFriOrSat(dateStr) {
  if(!dateStr) return false;
  const d=new Date(dateStr+"T12:00:00"); return d.getDay()===5||d.getDay()===6;
}

function getDriveFileId(url) {
  if(!url) return null;
  const text=String(url).trim();
  const patterns=[
    /\/file\/d\/([a-zA-Z0-9_-]+)/,
    /\/d\/([a-zA-Z0-9_-]+)/,
    /[?&]id=([a-zA-Z0-9_-]+)/,
    /[?&]file=([a-zA-Z0-9_-]+)/,
  ];
  for(const re of patterns){const m=text.match(re);if(m?.[1])return m[1];}
  return null;
}
function driveToDirectUrl(url) {
  if(!url) return null;
  const id=getDriveFileId(url);
  // Audio needs the download endpoint. The old export=view URL often returns an
  // HTML preview page, so the player looked like it started but never advanced.
  return id?`https://drive.google.com/uc?export=download&id=${id}`:String(url).trim();
}
function driveToViewUrl(url) {
  if(!url) return null;
  const id=getDriveFileId(url);
  return id?`https://drive.google.com/file/d/${id}/view`:String(url).trim();
}
function driveToEmbedUrl(url) {
  if(!url) return null;
  const id=getDriveFileId(url);
  return id?`https://drive.google.com/file/d/${id}/preview`:String(url).trim();
}

const DING_B64 = "";

function getSupabaseObjectPath(url, bucket) {
  try {
    const u = new URL(url);
    const publicMarker = `/storage/v1/object/public/${bucket}/`;
    const privateMarker = `/storage/v1/object/${bucket}/`;
    const idx = u.pathname.indexOf(publicMarker);
    if (idx >= 0) return decodeURIComponent(u.pathname.slice(idx + publicMarker.length));
    const idx2 = u.pathname.indexOf(privateMarker);
    if (idx2 >= 0) return decodeURIComponent(u.pathname.slice(idx2 + privateMarker.length));
  } catch (e) {}
  return null;
}

function pdfFetchCandidates(rawUrl) {
  const candidates = [];
  const original = rawUrl || "";
  const sourceUrl = driveToEmbedUrl(original);
  const viewUrl = driveToViewUrl(original);
  const supaPath = getSupabaseObjectPath(original, STORAGE_PDF_BUCKET);
  if (supaPath) {
    const encodedPath = encodeStoragePath(supaPath);
    candidates.push({
      url: `${SUPA_URL}/storage/v1/object/${STORAGE_PDF_BUCKET}/${encodedPath}`,
      headers: { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}` },
    });
    candidates.push({ url: `${SUPA_URL}/storage/v1/object/public/${STORAGE_PDF_BUCKET}/${encodedPath}` });
  }
  [viewUrl, sourceUrl, original].filter(Boolean).forEach(url => {
    if (!candidates.some(c => c.url === url)) candidates.push({ url });
  });
  return candidates;
}

async function fetchAsBlobUrl(candidates, mimeType = "application/pdf") {
  let lastError = null;
  for (const candidate of candidates) {
    try {
      const res = await fetch(candidate.url, { mode: "cors", headers: candidate.headers || {} });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      if (!blob || blob.size === 0) throw new Error("Empty file");
      const typedBlob = blob.type === mimeType ? blob : new Blob([blob], { type: mimeType });
      return URL.createObjectURL(typedBlob);
    } catch (e) {
      lastError = e;
    }
  }
  throw lastError || new Error("File could not be loaded.");
}


async function fetchAsArrayBuffer(candidates) {
  let lastError = null;
  for (const candidate of candidates) {
    try {
      const res = await fetch(candidate.url, { mode: "cors", headers: candidate.headers || {} });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const buffer = await res.arrayBuffer();
      if (!buffer || buffer.byteLength === 0) throw new Error("Empty file");
      return buffer;
    } catch (e) {
      lastError = e;
    }
  }
  throw lastError || new Error("File could not be loaded.");
}

const PDFJS_MODULE_URL = "https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.mjs";
const PDFJS_WORKER_URL = "https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.mjs";
let pdfJsModulePromise = null;
async function loadPdfJsModule() {
  if (!pdfJsModulePromise) {
    const dynamicImport = new Function("url", "return import(url)");
    pdfJsModulePromise = dynamicImport(PDFJS_MODULE_URL).then((pdfjs) => {
      pdfjs.GlobalWorkerOptions.workerSrc = PDFJS_WORKER_URL;
      return pdfjs;
    });
  }
  return pdfJsModulePromise;
}

async function downloadFromUrl(url, filename, mimeType = "application/octet-stream") {
  const objectUrl = await fetchAsBlobUrl([{ url }], mimeType).catch(async () => {
    const candidates = mimeType === "application/pdf" ? pdfFetchCandidates(url) : [{ url: driveToDirectUrl(url) || url }];
    return fetchAsBlobUrl(candidates, mimeType);
  });
  const a = document.createElement("a");
  a.href = objectUrl;
  a.download = filename || "download";
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(objectUrl), 1500);
}


