function InlineEdit({value,onSave,style={},placeholder="Edit..."}) {
  const [editing,setEditing]=useState(false);const [draft,setDraft]=useState(value);const ref=useRef(null);
  useEffect(()=>{if(editing)ref.current?.focus();},[editing]);useEffect(()=>{setDraft(value);},[value]);
  function commit(){setEditing(false);if(draft.trim()&&draft.trim()!==value)onSave(draft.trim());else setDraft(value);}
  if(editing) return <input ref={ref} value={draft} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={e=>{if(e.key==="Enter")commit();if(e.key==="Escape"){setDraft(value);setEditing(false);}}} style={{...style,border:`1.5px solid ${C.blue}`,borderRadius:6,padding:"2px 8px",outline:"none",fontFamily:"Raleway,sans-serif",background:"white",minWidth:120}} placeholder={placeholder}/>;
  return <span onClick={()=>setEditing(true)} title="Click to edit" style={{...style,cursor:"text",borderBottom:`1.5px dashed ${C.blue}55`,paddingBottom:1}}>{value}</span>;
}

function InlinePageEdit({value,onSave,style={},placeholder="—"}) {
  const display=value===null||value===undefined||value===""?placeholder:String(value);
  const [editing,setEditing]=useState(false);const [draft,setDraft]=useState(value===null||value===undefined?"":String(value));const ref=useRef(null);
  useEffect(()=>{if(editing)ref.current?.focus();},[editing]);
  useEffect(()=>{setDraft(value===null||value===undefined?"":String(value));},[value]);
  function commit(){setEditing(false);const clean=String(draft||"").trim();if(clean!==String(value??""))onSave(clean);else setDraft(value===null||value===undefined?"":String(value));}
  if(editing) return <input ref={ref} type="number" value={draft} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={e=>{if(e.key==="Enter")commit();if(e.key==="Escape"){setDraft(value===null||value===undefined?"":String(value));setEditing(false);}}} style={{...style,border:`1.5px solid ${C.blue}`,borderRadius:6,padding:"2px 6px",outline:"none",fontFamily:"Raleway,sans-serif",background:"white",width:58}} placeholder={placeholder}/>;
  return <span onClick={()=>setEditing(true)} title="Click to edit page number" style={{...style,cursor:"text",borderBottom:`1.5px dashed ${C.blue}55`,paddingBottom:1}}>{display}</span>;
}

function SectionHeaderTitle({value,onSave,editable,style={}}) {
  const [editing,setEditing]=useState(false);
  const [draft,setDraft]=useState(value);
  const ref=useRef(null);
  useEffect(()=>{setDraft(value);},[value]);
  useEffect(()=>{if(editing)ref.current?.focus();},[editing]);
  function commit(){
    const clean=String(draft||"").trim();
    setEditing(false);
    if(clean&&clean!==value)onSave(clean);
    else setDraft(value);
  }
  if(editable&&editing) return <input ref={ref} value={draft} onClick={e=>e.stopPropagation()} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={e=>{if(e.key==="Enter")commit();if(e.key==="Escape"){setDraft(value);setEditing(false);}}} style={{...style,border:`1.5px solid ${C.blue}`,borderRadius:6,padding:"2px 8px",outline:"none",fontFamily:"Raleway,sans-serif",background:"white",minWidth:120}}/>;
  return <span style={{display:"inline-flex",alignItems:"center",gap:8}}>
    <span style={style}>{value}</span>

  </span>;
}

